-- ── Trigger: auto-create profile on sign-up ───────────────────
-- Fires after a new row is inserted into auth.users.
-- Extracts full_name and avatar_url from OAuth metadata (Google, GitHub, etc.)

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiles (id, email, full_name, avatar_url)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(
      NEW.raw_user_meta_data->>'full_name',
      NEW.raw_user_meta_data->>'name',
      ''
    ),
    COALESCE(
      NEW.raw_user_meta_data->>'avatar_url',
      NEW.raw_user_meta_data->>'picture',
      NULL
    )
  );
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- ── Trigger: keep updated_at current ──────────────────────────

CREATE OR REPLACE FUNCTION public.handle_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER profiles_updated_at
  BEFORE UPDATE ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

-- ── Function: increment_scan_usage ────────────────────────────
-- Called before creating a scan to atomically check and increment the counter.
-- Returns TRUE if the scan was allowed, FALSE if the user has hit their limit.
-- Uses FOR UPDATE to prevent race conditions under concurrent requests.

CREATE OR REPLACE FUNCTION public.increment_scan_usage(user_uuid UUID)
RETURNS BOOLEAN AS $$
DECLARE
  v_used  INTEGER;
  v_limit INTEGER;
BEGIN
  SELECT scans_used, scan_limit
    INTO v_used, v_limit
    FROM public.profiles
   WHERE id = user_uuid
     FOR UPDATE;

  IF NOT FOUND THEN
    RETURN FALSE;
  END IF;

  IF v_used >= v_limit THEN
    RETURN FALSE;
  END IF;

  UPDATE public.profiles
     SET scans_used = scans_used + 1
   WHERE id = user_uuid;

  RETURN TRUE;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ── Function: reset_monthly_scans ─────────────────────────────
-- Resets scans_used to 0 and rolls billing_cycle_end forward by one month
-- for all users whose billing cycle has expired.
-- Intended to be called by Supabase pg_cron or a scheduled edge function.
--
-- pg_cron example (run in SQL editor after enabling the extension):
--   SELECT cron.schedule('reset-monthly-scans', '0 0 * * *', 'SELECT public.reset_monthly_scans()');

CREATE OR REPLACE FUNCTION public.reset_monthly_scans()
RETURNS void AS $$
BEGIN
  UPDATE public.profiles
     SET scans_used        = 0,
         billing_cycle_end = billing_cycle_end + INTERVAL '1 month'
   WHERE billing_cycle_end IS NOT NULL
     AND billing_cycle_end < NOW();
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

/**
 * Supabase-generated-style database types for CROBOT.
 *
 * These types mirror the SQL schema in supabase/migrations/ and are fully
 * compatible with the app-level types in src/types/index.ts.
 *
 * Usage:
 *   import { createClient } from '@supabase/supabase-js'
 *   import type { Database } from '@/types/database'
 *
 *   const supabase = createClient<Database>(url, key)
 *   const { data } = await supabase.from('scans').select('*')
 *   // data is typed as Tables<'scans'>[]
 */

import type { CroPillar, PageType, PlanType, ScanStatus, Severity, Effort } from "./index";

// ── Finding (JSONB shape stored inside scan_results.findings) ─
// Must stay in sync with the Finding interface in index.ts.

export interface DbFinding {
  id: string;
  title: string;
  severity: Severity;
  current_state: string;
  recommendation: string;
  ai_suggestion: string;
  is_premium: boolean;
  effort: Effort;
  estimated_lift: string;
  category: string;
}

// ── Table row shapes ──────────────────────────────────────────

export interface ProfileRow {
  id: string;
  email: string;
  full_name: string;
  company_name: string | null;
  website_url: string | null;
  avatar_url: string | null;
  plan: PlanType;
  scans_used: number;
  scan_limit: number;
  stripe_customer_id: string | null;
  stripe_subscription_id: string | null;
  billing_cycle_end: string | null;
  created_at: string;
  updated_at: string;
}

export interface ScanRow {
  id: string;
  user_id: string;
  url: string;
  favicon_url: string | null;
  page_title: string | null;
  page_type: PageType;
  status: ScanStatus;
  overall_score: number | null;
  issues_found: number;
  critical_issues: number;
  warnings: number;
  quick_wins: number;
  screenshot_url: string | null;
  device: "desktop" | "mobile" | "both";
  error_message: string | null;
  created_at: string;
  completed_at: string | null;
}

export interface ScanResultRow {
  id: string;
  scan_id: string;
  pillar: CroPillar;
  score: number;
  weight: number;
  benchmark: number;
  findings: DbFinding[];
  created_at: string;
}

export interface IntegrationRow {
  id: string;
  user_id: string;
  provider: "hotjar" | "google_analytics" | "clarity" | "search_console";
  access_token: string | null;
  refresh_token: string | null;
  is_active: boolean;
  connected_at: string;
}

// ── Insert types (required fields only, omit auto-generated) ──

export type ProfileInsert = Pick<ProfileRow, "id" | "email"> &
  Partial<
    Omit<ProfileRow, "id" | "email" | "created_at" | "updated_at">
  >;

export type ScanInsert = Pick<ScanRow, "user_id" | "url"> &
  Partial<Omit<ScanRow, "user_id" | "url" | "id" | "created_at">>;

export type ScanResultInsert = Pick<
  ScanResultRow,
  "scan_id" | "pillar" | "score" | "weight"
> &
  Partial<Omit<ScanResultRow, "scan_id" | "pillar" | "score" | "weight" | "id" | "created_at">>;

export type IntegrationInsert = Pick<
  IntegrationRow,
  "user_id" | "provider"
> &
  Partial<Omit<IntegrationRow, "user_id" | "provider" | "id" | "connected_at">>;

// ── Update types (all fields optional except primary key) ─────

export type ProfileUpdate = Partial<
  Omit<ProfileRow, "id" | "created_at">
>;

export type ScanUpdate = Partial<Omit<ScanRow, "id" | "user_id" | "created_at">>;

export type ScanResultUpdate = Partial<
  Omit<ScanResultRow, "id" | "scan_id" | "pillar" | "created_at">
>;

export type IntegrationUpdate = Partial<
  Omit<IntegrationRow, "id" | "user_id" | "provider" | "connected_at">
>;

// ── Supabase Database generic type ────────────────────────────

export interface Database {
  public: {
    Tables: {
      profiles: {
        Row: ProfileRow;
        Insert: ProfileInsert;
        Update: ProfileUpdate;
      };
      scans: {
        Row: ScanRow;
        Insert: ScanInsert;
        Update: ScanUpdate;
      };
      scan_results: {
        Row: ScanResultRow;
        Insert: ScanResultInsert;
        Update: ScanResultUpdate;
      };
      integrations: {
        Row: IntegrationRow;
        Insert: IntegrationInsert;
        Update: IntegrationUpdate;
      };
    };
    Views: Record<string, never>;
    Functions: {
      increment_scan_usage: {
        Args: { user_uuid: string };
        Returns: boolean;
      };
      reset_monthly_scans: {
        Args: Record<string, never>;
        Returns: void;
      };
    };
    Enums: Record<string, never>;
  };
}

// ── Convenience helpers ───────────────────────────────────────
// Use these for typed Supabase client access.

export type Tables<T extends keyof Database["public"]["Tables"]> =
  Database["public"]["Tables"][T]["Row"];

export type TablesInsert<T extends keyof Database["public"]["Tables"]> =
  Database["public"]["Tables"][T]["Insert"];

export type TablesUpdate<T extends keyof Database["public"]["Tables"]> =
  Database["public"]["Tables"][T]["Update"];

export type DbFunctions = Database["public"]["Functions"];

/**
 * analyze-url — Edge Function
 *
 * Orchestrates a full CRO audit for a given URL.
 * Expected to be called by the client after creating a scan row.
 *
 * Flow:
 *   1. Validate auth + scan ownership
 *   2. Update scan status → 'analyzing'
 *   3. Fetch page HTML and pass to AI (Anthropic Claude) for CRO analysis
 *   4. Call pagespeed function for performance metrics
 *   5. Write PillarResult rows into scan_results
 *   6. Update scan with overall_score, counts, status → 'completed'
 *
 * TODO: Implement when integrating Anthropic SDK and pagespeed function.
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
  );

  // TODO: Implement full CRO analysis pipeline
  return new Response(
    JSON.stringify({ status: "not_implemented" }),
    {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
      status: 501,
    },
  );
});

/**
 * pagespeed — Edge Function
 *
 * Fetches Google PageSpeed Insights data for a given URL and returns
 * structured performance metrics used to populate the page_performance pillar.
 *
 * Expected request body:
 *   { url: string; strategy?: 'mobile' | 'desktop' }
 *
 * Returns:
 *   { score: number; metrics: { lcp: number; fid: number; cls: number; fcp: number; ttfb: number } }
 *
 * Required env vars:
 *   PAGESPEED_API_KEY — Google Cloud API key with PageSpeed Insights API enabled
 *
 * TODO: Implement when PAGESPEED_API_KEY is provisioned.
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  // TODO: Implement PageSpeed Insights API call
  return new Response(
    JSON.stringify({ status: "not_implemented" }),
    {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
      status: 501,
    },
  );
});

/**
 * stripe-checkout — Edge Function
 *
 * Creates a Stripe Checkout Session for plan upgrades.
 *
 * Expected request body:
 *   { price_id: string; plan: 'pro' | 'agency'; billing: 'monthly' | 'annual' }
 *
 * Returns:
 *   { url: string } — redirect to Stripe-hosted checkout page
 *
 * Required env vars:
 *   STRIPE_SECRET_KEY
 *   NEXT_PUBLIC_SITE_URL  (for success/cancel redirects)
 *
 * Flow:
 *   1. Validate auth — must be signed-in user
 *   2. Fetch or create Stripe customer for user
 *   3. Create Checkout Session in subscription mode
 *   4. Return session URL
 *
 * TODO: Implement when Stripe is integrated.
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_ANON_KEY") ?? "",
    { global: { headers: { Authorization: req.headers.get("Authorization") ?? "" } } },
  );

  // TODO: Implement Stripe Checkout Session creation
  return new Response(
    JSON.stringify({ status: "not_implemented" }),
    {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
      status: 501,
    },
  );
});

/**
 * stripe-webhook — Edge Function
 *
 * Handles incoming Stripe webhook events to keep the profiles table in sync
 * with subscription state.
 *
 * Handled events:
 *   checkout.session.completed     → create/update subscription, set plan + billing_cycle_end
 *   customer.subscription.updated  → update plan on plan change
 *   customer.subscription.deleted  → downgrade to 'free', clear billing data
 *   invoice.payment_failed         → log failure (optional: email user)
 *
 * Required env vars:
 *   STRIPE_SECRET_KEY
 *   STRIPE_WEBHOOK_SECRET  (from Stripe dashboard → webhook endpoint)
 *
 * Security: Stripe-Signature header is verified before any processing.
 *
 * TODO: Implement when Stripe is integrated.
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

serve(async (req: Request) => {
  const signature = req.headers.get("stripe-signature");

  if (!signature) {
    return new Response(
      JSON.stringify({ error: "Missing Stripe-Signature header" }),
      { status: 400, headers: { "Content-Type": "application/json" } },
    );
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
  );

  // TODO: Implement Stripe webhook event handling
  return new Response(
    JSON.stringify({ status: "not_implemented" }),
    { status: 501, headers: { "Content-Type": "application/json" } },
  );
});

/**
 * send-email — Edge Function
 *
 * Sends transactional emails via Resend.
 *
 * Expected request body (union of email types):
 *   { type: 'scan_complete'; to: string; scan_id: string; score: number; issues: number }
 *   { type: 'welcome'; to: string; name: string }
 *   { type: 'upgrade_confirmation'; to: string; plan: 'pro' | 'agency' }
 *
 * Required env vars:
 *   RESEND_API_KEY
 *   FROM_EMAIL  (e.g. "CROBOT <noreply@crobot.app>")
 *
 * Security: Only callable with service role key or from another edge function.
 *
 * TODO: Implement when Resend is integrated.
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  // TODO: Implement Resend email dispatch
  return new Response(
    JSON.stringify({ status: "not_implemented" }),
    {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
      status: 501,
    },
  );
